/**
 * Quiz Centre. Questions are generated by the AI (only when asked), reviewed by the
 * student, and then graded deterministically on the server: multiple-choice and
 * true/false answers are compared exactly. Short-answer questions are not offered,
 * because honest grading of free text would need a human or an AI judge.
 * The AI's per-question explanations are labelled as AI-generated in the UI.
 */
const express = require('express');
const db = require('../database/db');
const ai = require('../services/aiService');
const { resolveSource } = require('../services/sourceText');
const activity = require('../lib/activity');
const v = require('../lib/validate');
const { HttpError, notFound, conflict } = require('../lib/errors');

const router = express.Router();

const parseOptions = (s) => {
  try {
    return s ? JSON.parse(s) : null;
  } catch (_) {
    return null;
  }
};

const questionView = (q, withAnswer) => ({
  id: q.id, position: q.position, type: q.type, question: q.question, options: parseOptions(q.options),
  ...(withAnswer ? { correct: q.correct, explanation: q.explanation } : {}),
});

function getQuiz(id) {
  const q = db.prepare('SELECT * FROM quizzes WHERE id = ?').get(id);
  if (!q) throw notFound('Quiz');
  return q;
}

const quizView = (q) => ({
  id: q.id, title: q.title, sourceType: q.source_type, sourceLabel: q.source_label, sourceRef: q.source_ref,
  aiGenerated: !!q.provider, createdAt: q.created_at,
});

router.get('/', (req, res) => {
  const rows = db
    .prepare(
      `SELECT q.*,
        (SELECT COUNT(*) FROM quiz_questions WHERE quiz_id = q.id) AS question_count,
        (SELECT COUNT(*) FROM quiz_attempts WHERE quiz_id = q.id AND completed_at IS NOT NULL) AS attempt_count,
        (SELECT MAX(ROUND(100.0 * score / total)) FROM quiz_attempts WHERE quiz_id = q.id AND completed_at IS NOT NULL) AS best_percent,
        (SELECT ROUND(100.0 * score / total) FROM quiz_attempts WHERE quiz_id = q.id AND completed_at IS NOT NULL ORDER BY id DESC LIMIT 1) AS last_percent
       FROM quizzes q ORDER BY q.created_at DESC, q.id DESC`
    )
    .all();
  res.json(rows.map((r) => ({ ...quizView(r), questionCount: r.question_count, attemptCount: r.attempt_count, bestPercent: r.best_percent, lastPercent: r.last_percent })));
});

router.post('/generate', async (req, res) => {
  const src = resolveSource(req.body);
  const count = v.int(req.body?.count, 'count', { min: 3, max: 15 }) || 5;
  const typesIn = Array.isArray(req.body?.types) && req.body.types.length ? req.body.types : ['mcq', 'tf'];
  const types = [...new Set(typesIn.map((t) => v.oneOf(t, 'question type', ['mcq', 'tf'], { required: true })))];
  const r = await ai.generateQuiz({ text: src.text, topic: src.topic, count, types, sourceLabel: src.type === 'document' ? src.label : null });
  const title = v.text(req.body?.title, 'Title', { max: 120 }) || r.title || `Quiz: ${src.label}`.slice(0, 120);
  const quizId = db.transaction(() => {
    const id = db
      .prepare('INSERT INTO quizzes (title, source_type, source_label, source_ref, provider, model) VALUES (?, ?, ?, ?, ?, ?)')
      .run(title, src.type, src.label, src.ref, r.provider, r.model).lastInsertRowid;
    const ins = db.prepare('INSERT INTO quiz_questions (quiz_id, position, type, question, options, correct, explanation) VALUES (?, ?, ?, ?, ?, ?, ?)');
    r.questions.forEach((q, i) => ins.run(id, i + 1, q.type, q.question, q.options ? JSON.stringify(q.options) : null, q.correct, q.explanation || null));
    return id;
  })();
  activity.log({ type: 'quiz_created', label: `Quiz created: ${title}`, refType: 'quiz', refId: quizId });
  res.status(201).json({ id: quizId });
});

router.get('/attempts/:attemptId', (req, res) => {
  res.json(attemptResult(v.id(req.params.attemptId, 'attemptId')));
});

router.get('/:id', (req, res) => {
  const quiz = getQuiz(v.id(req.params.id));
  const review = v.bool(req.query.review); // answers are only sent when reviewing, not when taking
  const questions = db.prepare('SELECT * FROM quiz_questions WHERE quiz_id = ? ORDER BY position').all(quiz.id);
  res.json({ ...quizView(quiz), questions: questions.map((q) => questionView(q, review)) });
});

router.delete('/:id', (req, res) => {
  const quiz = getQuiz(v.id(req.params.id));
  db.prepare('DELETE FROM quizzes WHERE id = ?').run(quiz.id); // questions, attempts, answers cascade
  res.json({ ok: true });
});

router.delete('/questions/:qid', (req, res) => {
  const q = db.prepare('SELECT * FROM quiz_questions WHERE id = ?').get(v.id(req.params.qid, 'questionId'));
  if (!q) throw notFound('Question');
  const left = db.prepare('SELECT COUNT(*) c FROM quiz_questions WHERE quiz_id = ?').get(q.quiz_id).c;
  if (left <= 1) throw new HttpError(400, 'invalid_input', 'A quiz needs at least one question. Delete the whole quiz instead.');
  db.transaction(() => {
    db.prepare('DELETE FROM quiz_questions WHERE id = ?').run(q.id);
    db.prepare('UPDATE quiz_questions SET position = position - 1 WHERE quiz_id = ? AND position > ?').run(q.quiz_id, q.position);
  })();
  res.json({ ok: true });
});

router.get('/:id/attempts', (req, res) => {
  const quiz = getQuiz(v.id(req.params.id));
  const rows = db
    .prepare('SELECT id, score, total, started_at, completed_at FROM quiz_attempts WHERE quiz_id = ? AND completed_at IS NOT NULL ORDER BY id DESC')
    .all(quiz.id);
  res.json(rows.map((r) => ({ id: r.id, score: r.score, total: r.total, percent: Math.round((100 * r.score) / r.total), completedAt: r.completed_at })));
});

router.post('/:id/attempts', (req, res) => {
  const quiz = getQuiz(v.id(req.params.id));
  const questions = db.prepare('SELECT * FROM quiz_questions WHERE quiz_id = ? ORDER BY position').all(quiz.id);
  if (!questions.length) throw new HttpError(400, 'invalid_input', 'This quiz has no questions.');
  const attemptId = db.prepare('INSERT INTO quiz_attempts (quiz_id, total) VALUES (?, ?)').run(quiz.id, questions.length).lastInsertRowid;
  res.status(201).json({ attemptId, quiz: quizView(quiz), questions: questions.map((q) => questionView(q, false)) });
});

function attemptResult(attemptId) {
  const a = db.prepare('SELECT * FROM quiz_attempts WHERE id = ?').get(attemptId);
  if (!a) throw notFound('Quiz attempt');
  const quiz = getQuiz(a.quiz_id);
  const rows = db
    .prepare(
      `SELECT q.*, ans.answer, ans.is_correct FROM quiz_questions q
       LEFT JOIN quiz_answers ans ON ans.question_id = q.id AND ans.attempt_id = ?
       WHERE q.quiz_id = ? ORDER BY q.position`
    )
    .all(attemptId, a.quiz_id);
  return {
    attemptId: a.id, quiz: quizView(quiz), score: a.score, total: a.total,
    percent: a.total ? Math.round((100 * (a.score || 0)) / a.total) : 0, completedAt: a.completed_at,
    results: rows.map((q) => ({ ...questionView(q, true), yourAnswer: q.answer ?? null, isCorrect: !!q.is_correct })),
  };
}

router.post('/attempts/:attemptId/submit', (req, res) => {
  const attemptId = v.id(req.params.attemptId, 'attemptId');
  const a = db.prepare('SELECT * FROM quiz_attempts WHERE id = ?').get(attemptId);
  if (!a) throw notFound('Quiz attempt');
  if (a.completed_at) throw conflict('This attempt has already been submitted.');
  const answers = req.body?.answers && typeof req.body.answers === 'object' ? req.body.answers : {};
  const questions = db.prepare('SELECT * FROM quiz_questions WHERE quiz_id = ?').all(a.quiz_id);
  let score = 0;
  db.transaction(() => {
    const ins = db.prepare('INSERT INTO quiz_answers (attempt_id, question_id, answer, is_correct) VALUES (?, ?, ?, ?)');
    for (const q of questions) {
      const given = answers[q.id] === undefined || answers[q.id] === null ? null : String(answers[q.id]);
      const ok = given !== null && given === q.correct ? 1 : 0; // deterministic exact comparison
      score += ok;
      ins.run(attemptId, q.id, given, ok);
    }
    db.prepare(`UPDATE quiz_attempts SET score = ?, total = ?, completed_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = ?`).run(score, questions.length, attemptId);
    const quiz = getQuiz(a.quiz_id);
    activity.log({
      type: 'quiz_completed',
      label: `Quiz Completed: ${quiz.title} · ${Math.round((100 * score) / (questions.length || 1))}%`,
      refType: 'quiz',
      refId: quiz.id,
    });
  })();
  res.json(attemptResult(attemptId));
});

module.exports = router;
